-- 3. MONTHLY REPORTS

-- 1: CVH Talwandi Sabo / 2025-03
DO $BODY$ DECLARE
  v_inst_id INTEGER := (SELECT institute_id FROM institutes WHERE org_id = 'TS_CVH_TALWANDI_SABO' LIMIT 1);
  v_staff_id INTEGER := (SELECT staff_id FROM staff WHERE user_id = 'ts_cvh_talwandi_sabo' LIMIT 1);
  v_report_id INTEGER;
BEGIN
  IF v_inst_id IS NULL OR v_staff_id IS NULL THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM monthly_reports WHERE institute_id = v_inst_id AND reporting_month = '2025-03') THEN RETURN; END IF;
  VALUES (v_inst_id, '2025-03', '2025-03-01', '2025-03-31', '2', 'Submitted', NOW(), v_staff_id)
  RETURNING report_id INTO v_report_id;

  SELECT v_report_id, vaccine_id, 200, 0, 0 FROM vaccines WHERE vaccine_code = 'BRUCELLOSIS' LIMIT 1
  ON CONFLICT (report_id, vaccine_id) DO NOTHING;
  SELECT v_report_id, semen_id, 0, 0, 0, 0, 0, 0, 134, 0, 0 FROM semen_types WHERE semen_code = 'HF_LOCAL' LIMIT 1
  ON CONFLICT (report_id, semen_type_id) DO NOTHING;
  SELECT v_report_id, semen_id, 0, 0, 0, 0, 0, 0, 42, 0, 0 FROM semen_types WHERE semen_code = 'CB_LOCAL' LIMIT 1
  ON CONFLICT (report_id, semen_type_id) DO NOTHING;
  SELECT v_report_id, semen_id, 0, 0, 0, 0, 0, 0, 124, 0, 0 FROM semen_types WHERE semen_code = 'SAHIWAL_LOCAL' LIMIT 1
  ON CONFLICT (report_id, semen_type_id) DO NOTHING;
  SELECT v_report_id, semen_id, 0, 0, 0, 0, 0, 0, 24, 0, 0 FROM semen_types WHERE semen_code = 'HF_ETT' LIMIT 1
  ON CONFLICT (report_id, semen_type_id) DO NOTHING;
  SELECT v_report_id, semen_id, 0, 0, 0, 0, 0, 0, 240, 0, 0 FROM semen_types WHERE semen_code = 'MURRAH' LIMIT 1
  ON CONFLICT (report_id, semen_type_id) DO NOTHING;
  SELECT v_report_id, semen_id, 0, 0, 0, 0, 0, 0, 20, 0, 0 FROM semen_types WHERE semen_code = 'NILI_RAVI' LIMIT 1
  ON CONFLICT (report_id, semen_type_id) DO NOTHING;
END $BODY$;

