-- Set reporting_institute_id for all Talwandi Sabo sub-institutes.
-- All TS_ institutes report to CVH Talwandi Sabo (tehsil HQ node for approval + rollup).
UPDATE institutes
SET reporting_institute_id = (SELECT institute_id FROM institutes WHERE org_id = 'TS_CVH_TALWANDI_SABO')
WHERE org_id LIKE 'TS_%'
  AND org_id != 'TS_CVH_TALWANDI_SABO'
  AND reporting_institute_id IS NULL;

